const rawInput = $input.first().json;
const body = rawInput.body ? rawInput.body : rawInput;

if (!body.seller_id) {
  return [{ json: { decision: 'REJECTED', reason: 'MISSING_SELLER_ID', message: 'seller_id is required.' } }];
}
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(body.seller_id)) {
  return [{ json: { decision: 'REJECTED', reason: 'INVALID_SELLER_ID_FORMAT', message: 'seller_id must be a valid UUID.' } }];
}

// Defaults to false (the existing, active-only view) when omitted, so
// every caller that only ever knew this endpoint before today keeps
// getting exactly what it got before.
return [{ json: { decision: 'VALID', seller_id: body.seller_id, show_archived: body.show_archived === true } }];

const sellerRows = $input.first().json;
const sellerRow = Array.isArray(sellerRows) ? sellerRows[0] : sellerRows;
const ctx = $('Validate Input').first().json;

if (!sellerRow) {
  return [{ json: { decision: 'REJECTED', reason: 'SELLER_NOT_FOUND', seller_id: ctx.seller_id, message: 'No seller record exists for this seller_id.' } }];
}
if (sellerRow.status !== 'active') {
  return [{ json: { decision: 'REJECTED', reason: 'SELLER_NOT_ACTIVE', seller_id: ctx.seller_id, seller_status: sellerRow.status, message: 'This seller account is not active (status: ' + sellerRow.status + '). Access is not permitted.' } }];
}

return [{ json: { decision: 'ELIGIBLE', seller_id: ctx.seller_id } }];

function collectAll(nodeItems) {
  // Zero real rows come back from PostgREST as `[]`. n8n's array-splitting
  // turns that into ZERO items, but this node's alwaysOutputData setting
  // then forces a single placeholder item through anyway so the workflow
  // doesn't just stop - and that placeholder's json is a bare {}, no keys
  // at all. A real row always carries the keys from the query's own
  // ?select= list, even when every value is null, so an empty-object check
  // safely tells the placeholder apart from a real row. Confirmed this was
  // the exact cause of a phantom "1 request" (and phantom "1 child," since
  // both this collection and the items collection produce the same
  // placeholder shape, which then collide under the same undefined
  // request_id key below) for any seller with zero real merge requests.
  if (nodeItems.length === 1 && Object.keys(nodeItems[0].json).length === 0) {
    return [];
  }
  // n8n may return a PostgREST array response as ONE item containing the
  // array, or split it into one item per row - handle both. Same defensive
  // pattern already used in wf14's Fetch Items node; missed reusing it here
  // the first time, which is exactly why Fetch Merge Requests' real 4 rows
  // never reached this node's output correctly.
  if (nodeItems.length === 1 && Array.isArray(nodeItems[0].json)) {
    return nodeItems[0].json;
  }
  return nodeItems.map(function(i) { return i.json; });
}

const ctx = $('Validate Input').first().json;
const requests = collectAll($('Fetch Merge Requests').all());
const items = collectAll($input.all());

// Group items by request_id for child-count and parent_sku lookup.
const itemsByRequest = {};
items.forEach(function(item) {
  if (!itemsByRequest[item.request_id]) itemsByRequest[item.request_id] = [];
  itemsByRequest[item.request_id].push(item);
});

const rows = requests.map(function(req) {
  const reqItems = itemsByRequest[req.request_id] || [];

  // OPEN QUESTION (still unconfirmed): 'parentage' column's real values are
  // unknown - may distinguish parent-rows from child-rows within this same
  // table. For now this counts ALL item rows for the request. Revisit once
  // real data lets you check `select distinct parentage from merge_request_items`.
  //
  // Confirmed live, not assumed: new-parent mode never inserts the anchor
  // listing into merge_request_items - it's tracked separately on
  // merge_requests (anchor_sku), exactly the same fact wf14's own matrix
  // generator already had to work around for the same reason. Without this,
  // every new-parent merge undercounts by exactly one - confirmed against a
  // real 4-child request that this node reported as 3.
  const hasUncountedAnchor = !!(req.is_new_parent && req.anchor_sku);
  const childCount = reqItems.length + (hasUncountedAnchor ? 1 : 0);

  const parentSkuItem = reqItems.find(function(i) { return i.parent_sku; });

  return {
    request_id: req.request_id,
    status: req.status,
    merge_type: req.merge_type,
    marketplace_id: req.marketplace_id,
    parent_sku: parentSkuItem ? parentSkuItem.parent_sku : null,
    child_count: childCount,
    is_new_parent: !!req.is_new_parent,
    dimension1_theme: req.dimension1_theme,
    dimension2_theme: req.dimension2_theme || null,
    created_at: req.created_at
  };
});

return [{ json: {
  decision: 'DASHBOARD_READY',
  seller_id: ctx.seller_id,
  count: rows.length,
  requests: rows
}}];
